@startuml

class Person {
  + Name : string
  + Email : string
}

class Student extends Person {
}

class Tutor extends Person {
  + BankAccount : string
}

class Subject {
  + Name : string
}

class TutoringOffer {
  + ExpertiseLevel : string
  + HourlyPrice : float
}

class Availability {
  + DayOfWeek : string
  + StartTime : time
  + EndTime : time
}

class TutoringRequest {
  + RequestedLevel : string
  + TargetDateTime : datetime
}

class TutoringSession {
  + ScheduledDateTime : datetime
  + Status : string
}

class Payment {
  + Amount : float
  + PaymentMethod : string
}

Tutor "1" -- "*" TutoringOffer : offers
TutoringOffer "*" -- "1" Subject : in
Tutor "1" -- "*" Availability : specifies
Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
TutoringRequest "1" -- "0..1" TutoringSession : results in
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
TutoringSession "1" -- "0..1" Payment : paid via
Tutor "1" -- "*" TutoringSession : provides discount to

@enduml

